// =============================================================================
// Phase 39: Incident Triage Engine - Recommendation Model
// =============================================================================
// TRIAGE SPEC LOCK v1.0.0
// Represents a triage recommendation for incident response.
// =============================================================================

namespace TerraFusion.Operations.Incidents;

/// <summary>
/// Represents a triage recommendation for incident response.
/// Generated by the deterministic triage engine, optionally refined by LLM.
/// </summary>
/// <remarks>
/// Recommendations should be:
/// - Actionable (specific steps, not generic advice)
/// - Component-targeted (mapped to known TerraFusion components)
/// - Auditable (traceable to the classification logic that produced them)
/// </remarks>
public record IncidentRecommendation
{
    /// <summary>
    /// Unique identifier for this recommendation.
    /// Format: "REC-{incidentId}-{sequence}" or similar.
    /// </summary>
    public required string Id { get; init; }

    /// <summary>
    /// Category of the recommendation.
    /// Maps to known TerraFusion components and action types.
    /// </summary>
    public required RecommendationCategory Category { get; init; }

    /// <summary>
    /// Human-readable recommendation text.
    /// Should be concise (1-3 sentences) and actionable.
    /// </summary>
    /// <example>
    /// "Restart the Atlas Forecast Orchestrator service. Check for recent deployments that may have introduced configuration drift."
    /// </example>
    public required string Text { get; init; }

    /// <summary>
    /// Confidence level for this recommendation.
    /// Based on correlation strength and historical accuracy.
    /// </summary>
    public required ConfidenceLevel Confidence { get; init; }

    /// <summary>
    /// Optional URL to a runbook or documentation for this action.
    /// Should link to Phase 37 dashboards or ops documentation.
    /// </summary>
    public string? RunbookUrl { get; init; }

    /// <summary>
    /// Optional priority within the incident (1 = highest priority).
    /// Used to order recommendations when presented to operators.
    /// </summary>
    public int? Priority { get; init; }

    /// <summary>
    /// Optional estimated time to implement this recommendation.
    /// Format: ISO 8601 duration (e.g., "PT15M" for 15 minutes).
    /// </summary>
    public string? EstimatedDuration { get; init; }

    /// <summary>
    /// Indicates if this recommendation was refined by the LLM explanation service.
    /// True = LLM contributed to the wording/details.
    /// False = Pure deterministic recommendation.
    /// </summary>
    public bool LlmRefined { get; init; } = false;
}
